    padding: 28px 24px;
    color: white;
    text-align: center;
    position: relative;
    overflow: hidden;
    margin-bottom: 16px;

    &::before {
        content: '';
        position: absolute;
        inset: 0;
        background-image: radial-gradient(circle, rgba(255,255,255,0.06) 1.5px, transparent 1.5px);
        background-size: 20px 20px;
        pointer-events: none;
    }
}

.admin-helper-card__alex {
    width: 100px;
    margin: 0 auto 16px;
    filter: drop-shadow(0 16px 24px rgba(0,0,0,0.3));
    position: relative;
    z-index: 1;
}

.admin-helper-card__title {
    font-size: 1rem;
    font-weight: 800;
    letter-spacing: -0.02em;
    margin-bottom: 8px;
    position: relative;
    z-index: 1;
}

.admin-helper-card__text {
    font-size: 0.84rem;
    opacity: 0.8;
    line-height: 1.65;
    position: relative;
    z-index: 1;
}

/* Apunte contextual dentro de la tarjeta: lo escribe el JS cuando ya hay datos
   suficientes (en Suplencias, el día concreto que hay que tocar en la rejilla).
   Vacío no ocupa nada, así que la tarjeta no reserva hueco de más. */
