    label:hover {
        border-color: var(--col-bilbao);
        background: rgba(77, 138, 187, 0.03);
    }
}

.admin-role-card__icon {
    font-size: 1.4rem;
    margin-bottom: 8px;
    color: var(--col-bilbao);
}

.admin-role-card__name {
    font-size: 0.88rem;
    font-weight: 700;
    color: var(--col-herencia);
    margin-bottom: 4px;
}

.admin-role-card__desc {
    font-size: 0.71rem;
    color: var(--text-gray);
    line-height: 1.5;
}

/* AVATAR UPLOAD */
.admin-avatar-upload {
    display: flex;
    align-items: center;
    gap: 20px;
}

.admin-avatar-preview {
    width: 72px;
    height: 72px;
    border-radius: 50%;
    background: linear-gradient(135deg, var(--col-bilbao), var(--col-espiritu));
    display: flex;
    align-items: center;
    justify-content: center;
    color: white;
    font-size: 1.6rem;
    font-weight: 800;
    flex-shrink: 0;
    overflow: hidden;

    img {
        width: 100%;
        height: 100%;
        object-fit: cover;
    }
}

.admin-avatar-btn {
    display: inline-flex;
    align-items: center;
    gap: 6px;
    padding: 8px 16px;
    border-radius: var(--radius-sm);
    font-size: 0.82rem;
    font-weight: 600;
    cursor: pointer;
    font-family: 'Outfit', sans-serif;
    border: 1.5px solid #E2E8F0;
    background: transparent;
    color: var(--text-gray);
    transition: all var(--transition-fast);
    text-decoration: none;

    &:hover {
        border-color: var(--col-bilbao);
        color: var(--col-bilbao);
    }
}

/* BREADCRUMB */
.admin-breadcrumb {
    display: flex;
    align-items: center;
    gap: 6px;
    font-size: 0.82rem;
    color: var(--text-gray);

    a {
        color: var(--col-bilbao);
        text-decoration: none;
        font-weight: 600;

        &:hover {
            color: var(--col-herencia);
        }
    }

    i {
        font-size: 0.65rem;
        opacity: 0.45;
    }
}

