    grid-template-columns: 1fr 300px;
    gap: 24px;
    align-items: start;

    @media (max-width: 1100px) {
        grid-template-columns: 1fr;
    }
}

.article-editor-main {
    display: flex;
    flex-direction: column;
    gap: 20px;
}

.article-editor-sidebar {
    display: flex;
    flex-direction: column;
    gap: 16px;
    position: sticky;
    top: 88px;
}

