    background: #fff;
    border-radius: var(--radius-card);
    border: 1px solid #E8EDF3;
    padding: 24px 28px 20px;
}

.article-title-input {
    width: 100%;
    border: none;
    outline: none;
    font-family: 'Outfit', sans-serif;
    font-size: clamp(1.4rem, 2.5vw, 1.9rem);
    font-weight: 800;
    color: var(--col-herencia);
    letter-spacing: -0.03em;
