    padding-top: 12px;
    border-top: 1px solid #F0F4F8;
    font-size: 0.78rem;
    color: var(--text-gray);
    display: flex;
    align-items: center;
    gap: 6px;
    flex-wrap: wrap;
}

.article-slug-label {
    font-weight: 700;
    color: var(--col-bilbao);
}

.article-slug-value {
    font-family: monospace;
    background: #F8FAFC;
    border: 1px solid #E8EDF3;
    border-radius: 5px;
    padding: 3px 8px;
    color: var(--text-gray);
    letter-spacing: 0.01em;

    em {
        color: var(--col-bilbao);
        font-style: normal;
    }
