    font-family: 'Outfit', sans-serif;

    &:hover {
        background: var(--col-herencia);
    }
}

.image-upload-zone__hint {
    font-size: 0.76rem;
    color: #A0AEC0;
    margin-top: 10px;
}

.image-upload-zone__preview {
    width: 100%;
    height: 240px;
    object-fit: cover;
    display: block;
}

.image-upload-zone__overlay {
    position: absolute;
    inset: 0;
    background: rgba(55, 76, 105, 0.55);
    display: flex;
    align-items: center;
    justify-content: center;
    opacity: 0;
    transition: opacity var(--transition-fast);

    .image-upload-zone--has-image:hover & {
        opacity: 1;
    }
}

.image-upload-zone__change-btn {
    display: inline-flex;
    align-items: center;
    gap: 8px;
    padding: 10px 22px;
    border-radius: var(--radius-pill);
    background: rgba(255, 255, 255, 0.2);
    backdrop-filter: blur(6px);
    border: 1.5px solid rgba(255, 255, 255, 0.35);
    color: white;
    font-size: 0.875rem;
    font-weight: 700;
    cursor: pointer;
    font-family: 'Outfit', sans-serif;
    transition: background var(--transition-fast);

    &:hover {
        background: rgba(255, 255, 255, 0.3);
    }
}

/* ── Image change trigger (siempre visible bajo el upload zone) ── */
.image-change-trigger {
    display: inline-flex;
    align-items: center;
    gap: 7px;
    margin-top: 10px;
    padding: 8px 18px;
    border-radius: var(--radius-pill);
    border: 1.5px solid #CBD5E0;
    background: #fff;
    color: #374C69;
    font-size: 0.82rem;
    font-weight: 700;
    font-family: 'Outfit', sans-serif;
    cursor: pointer;
    transition: border-color var(--transition-fast), background var(--transition-fast), color var(--transition-fast);

    &:hover {
        border-color: var(--col-bilbao);
        background: rgba(77, 138, 187, 0.06);
        color: var(--col-bilbao);
    }
}

/* ── Alex tip ── */
.alex-tip {
    display: flex;
    align-items: flex-end;
    gap: 16px;
    background: linear-gradient(135deg, rgba(77, 138, 187, 0.06) 0%, rgba(55, 76, 105, 0.04) 100%);
    border: 1px solid rgba(77, 138, 187, 0.15);
    border-radius: var(--radius-card);
    padding: 20px 24px 20px 16px;

    &--edit {
        background: linear-gradient(135deg, rgba(72, 187, 120, 0.06) 0%, rgba(39, 103, 73, 0.04) 100%);
        border-color: rgba(72, 187, 120, 0.2);
    }
}

.alex-tip__img {
    width: 70px;
    flex-shrink: 0;
    filter: drop-shadow(0 8px 16px rgba(0, 0, 0, 0.15));
    align-self: flex-end;
}

.alex-tip__bubble {
    flex: 1;

    strong {
        display: block;
        font-size: 0.84rem;
        font-weight: 800;
        color: var(--col-herencia);
        margin-bottom: 5px;
    }

    p {
        font-size: 0.83rem;
        color: var(--text-gray);
        line-height: 1.6;
        margin: 0;
    }
}

/* ── Editor side panel ── */
.editor-panel {
    background: #fff;
    border-radius: var(--radius-card);
    border: 1px solid #E8EDF3;
    overflow: hidden;
}

.editor-panel__header {
    padding: 14px 18px;
    background: #F8FAFC;
    border-bottom: 1px solid #F0F4F8;
    font-size: 0.78rem;
    font-weight: 800;
    text-transform: uppercase;
    letter-spacing: 0.09em;
    color: var(--col-herencia);
    display: flex;
    align-items: center;
    gap: 8px;

    i {
        color: var(--col-bilbao);
        font-size: 0.82rem;
    }
}

.editor-panel__body {
    padding: 16px 18px;
    display: flex;
    flex-direction: column;
    gap: 12px;
}

.editor-panel__divider {
    height: 1px;
    background: #F0F4F8;
    margin: 4px 0;
}

.editor-panel__actions {
    display: flex;
    flex-direction: column;
    gap: 8px;

    .admin-btn {
        width: 100%;
        justify-content: center;
        padding: 11px 16px;
        font-size: 0.88rem;
    }
}

.editor-panel__hint {
    font-size: 0.76rem;
    color: var(--text-gray);
    line-height: 1.5;
    margin: 0;

    i {
        color: var(--col-bilbao);
        margin-right: 3px;
    }
}

.editor-panel__link {
    display: inline-flex;
    align-items: center;
    gap: 5px;
    font-size: 0.78rem;
    font-weight: 600;
    color: var(--col-bilbao);
    text-decoration: none;
    margin-top: 4px;

    &:hover {
        color: var(--col-herencia);
    }
}

/* ── Secondary button ── */
.admin-btn--secondary {
    background: #F8FAFC;
    color: var(--col-herencia);
    border: 1.5px solid #E2E8F0;

    &:hover {
        background: #EDF2F7;
        border-color: #CBD5E0;
        transform: translateY(-1px);
    }
}

/* ── Topbar preview button ── */
.admin-topbar__preview-btn {
    display: inline-flex;
    align-items: center;
    gap: 7px;
    padding: 8px 16px;
    border-radius: var(--radius-pill);
    border: 1.5px solid #E2E8F0;
    background: transparent;
    color: var(--text-gray);
    font-size: 0.84rem;
    font-weight: 600;
    text-decoration: none;
    transition: all var(--transition-fast);

    &:hover {
        border-color: var(--col-bilbao);
        color: var(--col-bilbao);
        background: rgba(77, 138, 187, 0.04);
    }
}

/* ── Edit notice bar ── */
.admin-edit-notice {
    display: flex;
    align-items: center;
    gap: 8px;
    padding: 12px 20px;
    background: rgba(77, 138, 187, 0.06);
    border: 1px solid rgba(77, 138, 187, 0.15);
    border-radius: var(--radius-md);
    font-size: 0.83rem;
    color: var(--text-gray);
    margin-bottom: 20px;
    flex-wrap: wrap;

    i {
        color: var(--col-bilbao);
        flex-shrink: 0;
    }

    strong {
        color: var(--col-herencia);
    }
}

/* ── Danger zone label ── */
.admin-danger-zone__label {
    font-size: 0.9rem;
    font-weight: 700;
    color: var(--col-herencia);
    margin-bottom: 4px;
}

/* ── Panels with field groups ── */
.editor-panel__body .admin-field-group:first-child {
    margin-top: 0;
}

/* =====================================================
   ALERTAS DEL PANEL
===================================================== */

.admin-alerta {
    display: flex;
    align-items: flex-start;
    gap: 12px;
    padding: 14px 20px;
    border-radius: var(--radius-md);
    font-size: .88rem;
    line-height: 1.55;
    margin-bottom: 20px;

    > i { flex-shrink: 0; margin-top: 2px; font-size: .95rem; }

    &--error {
        background: #fff5f5;
        border: 1.5px solid #fed7d7;
        color: #c53030;
        > i { color: #c53030; }
    }

    &--success {
        background: #f0fff4;
        border: 1.5px solid #9ae6b4;
        color: #276749;
        > i { color: #38a169; }
    }
}

.admin-alerta__list {
    margin: 0;
    padding: 0 0 0 16px;
    li + li { margin-top: 4px; }
}

.admin-alerta__close {
    margin-left: auto;
    background: none;
    border: none;
    cursor: pointer;
    color: inherit;
    opacity: .6;
    padding: 2px 4px;
    font-size: .85rem;
    flex-shrink: 0;
    &:hover { opacity: 1; }
}

/* =====================================================
   VALIDACIÓN INTERACTIVA DE CAMPOS
===================================================== */

/* Estado válido / inválido en el wrapper */
.admin-form__input-wrapper {
    position: relative;

    &.has-valid .admin-form__input   { border-color: #38a169; padding-right: 42px; }
    &.has-invalid .admin-form__input { border-color: #e53e3e; padding-right: 42px; }
}

/* Íconos de estado flotantes */
.field-icon {
    position: absolute;
    right: 14px;
    top: 50%;
    transform: translateY(-50%);
    font-size: .85rem;
    pointer-events: none;
    opacity: 0;
    transition: opacity .15s;

    &--valid  { color: #38a169; }
    &--invalid { color: #e53e3e; }
}

.has-valid   .field-icon--valid   { opacity: 1; }
.has-invalid .field-icon--invalid { opacity: 1; }

/* Mensajes de campo */
.field-msg {
    display: block;
    font-size: .76rem;
    margin-top: 5px;
    line-height: 1.4;
    min-height: 1em;

    &--valid   { color: #38a169; }
    &--invalid { color: #e53e3e; }
}

/* Medidor de fortaleza de contraseña */
.password-strength {
    margin-top: 8px;
    display: flex;
    align-items: center;
    gap: 10px;
}

.password-strength__bar {
    flex: 1;
    height: 4px;
    background: #E2E8F0;
    border-radius: 99px;
    overflow: hidden;
}

.password-strength__fill {
    display: block;
    height: 100%;
    width: 0;
    border-radius: 99px;
    transition: width .3s, background .3s;
}

.password-strength__label {
    font-size: .72rem;
    font-weight: 700;
    min-width: 60px;
    text-align: right;
}

/* =====================================================
   EMPTY STATE
===================================================== */

.admin-empty-state {
    padding: 56px 24px;
    text-align: center;
    display: flex;
    flex-direction: column;
    align-items: center;
    gap: 16px;
}

.admin-empty-state__img {
    width: 110px;
    opacity: .7;
    filter: drop-shadow(0 8px 16px rgba(0,0,0,.12));
}

.admin-empty-state__text {
    font-size: .95rem;
    color: var(--text-gray);
}

/* =====================================================
   PANEL COUNT BADGE
===================================================== */

.admin-panel__count {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    min-width: 22px;
    height: 22px;
    padding: 0 6px;
    border-radius: 99px;
    background: rgba(77,138,187,.1);
    color: var(--col-bilbao);
    font-size: .72rem;
    font-weight: 800;
    /* El `gap` de .admin-panel__title ya lo separa; con el margen sumaba 18px y
       quedaba descolgado del texto. */
    margin-left: 0;
}

/* =====================================================
   WYSIWYG EDITOR — CREAR / EDITAR ARTÍCULO
===================================================== */

.wysiwyg-editor {
    min-height: 480px;
    padding: 24px 28px;
    border: 1.5px solid #E2E8F0;
    border-top: none;
    border-radius: 0 0 var(--radius-sm) var(--radius-sm);
    font-family: 'Outfit', sans-serif;
    font-size: 1.05rem;
    color: var(--col-texto);
    line-height: 1.8;
    background: #fff;
    outline: none;
    cursor: text;
    transition: border-color var(--transition-fast), box-shadow var(--transition-fast);
    word-break: break-word;
    overflow-wrap: break-word;

    &:focus {
        border-color: var(--col-bilbao);
        box-shadow: 0 0 0 3px rgba(77, 138, 187, 0.08);
    }

    &.is-empty::before {
        content: attr(data-placeholder);
        color: #A0AEC0;
        pointer-events: none;
        display: block;
    }

    h2 {
        font-size: 1.55rem;
        font-weight: 800;
        color: var(--col-herencia);
        margin: 1.4em 0 .45em;
        letter-spacing: -.025em;
        line-height: 1.2;
    }

    h3 {
        font-size: 1.2rem;
        font-weight: 700;
        color: var(--col-herencia);
        margin: 1.2em 0 .4em;
        line-height: 1.3;
    }

    p {
        margin: 0 0 1em;
        &:last-child { margin-bottom: 0; }
    }

    strong, b { font-weight: 700; }
    em, i     { font-style: italic; }

    blockquote {
        margin: 1.4em 0;
        padding: .9em 1.4em;
        border-left: 4px solid var(--col-bilbao);
        background: rgba(77, 138, 187, 0.05);
        border-radius: 0 var(--radius-sm) var(--radius-sm) 0;
        color: var(--text-gray);
        font-style: italic;

        p { margin: 0; }
    }

    ul, ol {
        margin: .8em 0;
        padding-left: 1.6em;
    }

    li {
        margin: .28em 0;
        line-height: 1.65;
    }

    a {
        color: var(--col-bilbao);
        text-decoration: underline;
        text-underline-offset: 2px;
    }

    *:first-child { margin-top: 0 !important; }
}

/* Toolbar button active state */
.editor-toolbar__btn--active {
    background: rgba(77, 138, 187, 0.18) !important;
    color: var(--col-bilbao) !important;
}

/* =====================================================
   SEO HINT — TÍTULO
===================================================== */

.seo-hint {
    font-size: .74rem;
    font-weight: 600;
    transition: color var(--transition-fast);

    &.seo--good  { color: #38a169; }
    &.seo--warn  { color: #d97706; }
    &.seo--bad   { color: #e53e3e; }
    &.seo--empty { color: #A0AEC0; }
}

/* ── Slug edit button ── */
.article-slug-edit-btn {
    display: inline-flex;
    align-items: center;
    gap: 4px;
    font-size: .71rem;
    font-weight: 600;
    color: var(--col-bilbao);
    background: none;
    border: none;
    cursor: pointer;
    padding: 2px 5px;
    border-radius: 4px;
    transition: background var(--transition-fast);
    font-family: 'Outfit', sans-serif;

    &:hover { background: rgba(77, 138, 187, 0.1); }
}

/* =====================================================
   TIEMPO DE LECTURA — DISPLAY
===================================================== */

.reading-time-display {
    display: flex;
    align-items: baseline;
    gap: 5px;
    font-size: 2.2rem;
    font-weight: 800;
    color: var(--col-herencia);
    line-height: 1;
}

.reading-time-unit {
    font-size: .9rem;
    font-weight: 600;
    color: var(--text-gray);
}

/* =====================================================
   TAG PILLS SYSTEM
===================================================== */

.tag-input-wrap {
    display: flex;
    flex-wrap: wrap;
    gap: 5px;
    padding: 8px 10px;
    border: 1.5px solid #E2E8F0;
    border-radius: var(--radius-sm);
    background: #fff;
    min-height: 44px;
    align-items: center;
    cursor: text;
    transition: border-color var(--transition-fast), box-shadow var(--transition-fast);

    &:focus-within {
        border-color: var(--col-bilbao);
        box-shadow: 0 0 0 3px rgba(77, 138, 187, 0.12);
    }
}

.tag-pill {
    display: inline-flex;
    align-items: center;
    gap: 4px;
    padding: 3px 8px 3px 10px;
    background: rgba(77, 138, 187, 0.1);
    color: var(--col-bilbao);
    border: 1px solid rgba(77, 138, 187, 0.2);
    border-radius: 99px;
    font-size: .75rem;
    font-weight: 600;
    white-space: nowrap;
    animation: tagPop .18s ease both;
}

@keyframes tagPop {
    from { transform: scale(.7); opacity: 0; }
    to   { transform: scale(1);  opacity: 1; }
}

.tag-pill__remove {
    background: none;
    border: none;
    cursor: pointer;
    color: var(--col-bilbao);
    font-size: .82rem;
    padding: 0 2px;
    line-height: 1;
    opacity: .55;
    transition: opacity var(--transition-fast);

    &:hover { opacity: 1; }
}

.tag-input-field {
    border: none;
    outline: none;
    font-family: 'Outfit', sans-serif;
    font-size: .85rem;
    color: var(--col-texto);
    flex: 1;
    min-width: 90px;
    padding: 2px 0;
    background: transparent;

    &::placeholder { color: #A0AEC0; }
}

/* =====================================================
   ALEX TIP — LISTA DE TIPS SEO
===================================================== */

.alex-tip__list {
    margin: 6px 0 0;
    padding: 0;
    list-style: none;
    display: flex;
    flex-direction: column;
    gap: 5px;

    li {
        font-size: .79rem;
        color: var(--text-gray);
        line-height: 1.5;
        display: flex;
        align-items: flex-start;
        gap: 7px;

        i {
            color: #38a169;
            font-size: .7rem;
            margin-top: 3px;
            flex-shrink: 0;
        }

        strong { color: var(--col-herencia); }
    }
}

/* =====================================================
   FLUJO EDITORIAL — nuevos estilos
===================================================== */

// ── Badge sidebar de notificaciones no leídas ──────────────────────────────
.admin-nav__badge {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    min-width: 18px;
    height: 18px;
    padding: 0 5px;
    border-radius: 99px;
    background: #ef4444;
    color: #fff;
    font-size: .65rem;
    font-weight: 800;
    margin-left: auto;
    flex-shrink: 0;
    line-height: 1;
}

.admin-sidebar--collapsed .admin-nav__badge {
    position: absolute;
    top: 4px;
    right: 4px;
    min-width: 8px;
    height: 8px;
    padding: 0;
    font-size: 0;
    border-radius: 50%;
}

// ── Estado "Requiere cambios" badge en tablas ──────────────────────────────
.admin-badge--changes {
    background: #fee2e2;
    color: #991b1b;
    border: 1px solid #fca5a5;
    display: inline-flex;
    align-items: center;
    gap: 4px;
    font-size: .72rem;
    font-weight: 700;
    padding: 2px 8px;
    border-radius: 99px;
    white-space: nowrap;
}

// ── Modal de confirmación "Enviar a revisión" ──────────────────────────────
.revision-confirm-modal {
    position: fixed;
    inset: 0;
    background: rgba(15,23,42,.5);
    backdrop-filter: blur(4px);
    z-index: 9100;
    display: flex;
    align-items: center;
    justify-content: center;
    opacity: 0;
    pointer-events: none;
    transition: opacity .2s;

    &.is-open {
        opacity: 1;
        pointer-events: all;
    }
}

.revision-confirm-modal__card {
    background: #fff;
    border-radius: 18px;
    padding: 32px 28px 24px;
    max-width: 420px;
    width: 92%;
    box-shadow: 0 28px 64px rgba(15,23,42,.2);
    transform: scale(.88);
    transition: transform .25s cubic-bezier(.34,1.56,.64,1);

    .revision-confirm-modal.is-open & {
        transform: scale(1);
    }
}

.revision-confirm-modal__icon {
    width: 56px;
    height: 56px;
    background: #eff6ff;
    border: 2px solid #bfdbfe;
    border-radius: 50%;
    display: flex;
    align-items: center;
    justify-content: center;
    margin: 0 auto 16px;
    font-size: 1.4rem;
    color: #4267ac;
}

.revision-confirm-modal__title {
    font-size: 1.1rem;
    font-weight: 800;
    color: #0f172a;
    text-align: center;
    margin-bottom: 10px;
    letter-spacing: -.02em;
}

.revision-confirm-modal__text {
    font-size: .88rem;
    color: #475569;
    text-align: center;
    line-height: 1.6;
    margin-bottom: 22px;
}

.revision-confirm-modal__actions {
    display: flex;
    gap: 10px;

    .admin-btn { flex: 1; justify-content: center; }
}

// ── Panel diff version_pendiente (en el sidebar de revisión del admin) ──────
.rev-pending-diff {
    background: #f0f9ff;
    border: 1px solid #bae6fd;
    border-radius: 10px;
    padding: 12px 14px;
    margin-top: 10px;
    font-size: .82rem;
}

.rev-pending-diff__label {
    font-weight: 700;
    color: #0369a1;
    margin-bottom: 8px;
    display: flex;
    align-items: center;
    gap: 6px;
    font-size: .78rem;
}

.rev-diff-row {
    display: flex;
    gap: 8px;
    margin-bottom: 5px;
    line-height: 1.5;
}

.rev-diff-row__key {
    font-weight: 700;
    color: #0369a1;
    white-space: nowrap;
    flex-shrink: 0;
    min-width: 72px;
}

.rev-diff-row__val {
    color: #1e3a5f;
    word-break: break-word;
}

.rev-diff-row__val--modified {
    color: #d97706;
    font-style: italic;
}

/* El bloque .notif-* (la lista de notificaciones antigua) se eliminó: la bandeja
   se reescribió con el sistema .nt-* de src/scss/admin/_admin-notificaciones.scss y
   ninguna vista usaba ya estas clases. */

// ── Alex notification modal ───────────────────────────────────────────────
.alex-modal {
    position: fixed;
    inset: 0;
    z-index: 9999;
    background: rgba(0, 0, 0, .55);
    display: flex;
    align-items: center;
    justify-content: center;
    opacity: 0;
    pointer-events: none;
    transition: opacity .3s ease;
    backdrop-filter: blur(2px);
}

.alex-modal.is-open {
    opacity: 1;
    pointer-events: all;
}

.alex-modal__card {
    background: #fff;
    border-radius: 20px;
    padding: 28px;
    display: flex;
    /* El texto arrancaba arriba mientras Alex iba anclado al pie de la tarjeta:
       con dos o tres líneas de mensaje el desfase era de medio bloque. */
    align-items: center;
    gap: 22px;
    max-width: 500px;
    width: calc(100% - 32px);
    box-shadow: 0 24px 60px rgba(0, 0, 0, .22);
    transform: scale(.88) translateY(20px);
    transition: transform .35s cubic-bezier(.34, 1.56, .64, 1), opacity .3s;
    opacity: 0;
}

.alex-modal.is-open .alex-modal__card {
    transform: scale(1) translateY(0);
    opacity: 1;
}

.alex-modal__img {
    width: 130px;
    max-height: 190px;
    object-fit: contain;
    flex-shrink: 0;
    align-self: center;
}

.alex-modal__body {
    display: flex;
    flex-direction: column;
    justify-content: center;
    gap: 10px;
    flex: 1;
    min-width: 0;
}

.alex-modal__tipo {
    font-size: 1.15rem;
    font-weight: 800;
    color: #0F172A;
    margin: 0;
}

.alex-modal__msg {
    font-size: .9rem;
    color: #374C69;
    line-height: 1.6;
    margin: 0;
}

.alex-modal__actions {
    display: flex;
